INPUTS = [
('Sets',r'$\mathcal W$: products, indexed by $w$; $\mathcal I$: wafer-route tasks, indexed by $i$, including each product route and each auxiliary-wafer loan route.'),
('Set/binary inputs',r'$\mathcal S=\{A,V\}$: source regions, indexed by $s$ (atmospheric/vacuum). $\sigma=0/1$: single/dual source. $\chi_{is}=1$: task $i$ originates in region $s$.'),
('Inputs/set',r'$\ell_w$: LP of product $w$; $m_w\in\{\zeta,\psi\}$: its prescribed recipe; $\mathcal C(m)$: chambers compatible with operation type $m$.'),
('Integer input',r'Number of product wafers, $N=|\mathcal W|=N_\zeta+N_\psi$; excludes auxiliary wafers.'),
('Sets',r'$\mathcal P$: candidate PW pairs, indexed by $p$; $\mathcal M=\{\zeta,\psi,\mathrm{cl}\}$: operation types, indexed by $m$, denoting $4\times1$ production, $2\times2$ production, and cleaning.'),
('Set',r'$\mathcal C=\{\mathrm{CH1,CH2}\}$: process chambers, indexed by $c$.'),
('Index set',r'$\mathcal Q_c=\{1,\ldots,Q_{\max}\}$: candidate chamber cycles in chamber $c$, indexed by $q$.'),
('Counts/bounds',r'$N_\zeta,N_\psi$: product counts by recipe (recipe-label subscripts). $T$: upper bound on total production cycles; $J_{\max}$: upper bound on total cleanings across the tool.'),
('Capacity bounds',r'$P_{\max}$: candidate-pair capacity for the entire lot. $Q_{\max}$: tool-wide bound on production-plus-cleaning cycles, also used as each chamber\textquotesingle s candidate capacity. The label max denotes an upper bound.'),
('Integer input',r'Maximum production count in one chamber since its initially clean state or latest cleaning. Cleaning is optional at a valid boundary after 1 to $H-1$ cycles and mandatory at $H$.'),
('Sets',r'$\mathcal O$: candidate physical actions, indexed by $o,o^{\prime}$; $\mathcal A$: precedence arcs, where $(o,o^{\prime})$ requires $o$ before $o^{\prime}$.'),
('Conditional arc sets',r'$\mathcal A^{\rm int}$: common chamber-internal arcs (int is a label); $\mathcal A_{is}(\gamma)$: supply/return arcs for task $i$ from region $s$, activated by transfer choices $\gamma$.'),
('Time inputs',r'$d_o$: fixed duration of action $o$; $r_c$: half-turn duration of chamber $c$, both in seconds.'),
('Time inputs',r'$\delta_{oo^{\prime}}$: minimum precedence gap; $\rho^r_{oo^{\prime}}$: repositioning/reset time on resource $r$ between tasks $o,o^{\prime}$; $\rho^{\rm VTR}_{cc^{\prime}}$: VTR travel time from chamber $c$ to $c^{\prime}$.'),
('Time bounds',r'$M$: valid large constant for conditional timing constraints; $\overline R_{wr}$: maximum residency of wafer $w$ in constrained equipment or route region $r$, in seconds.'),
('Time inputs',r'$\overline T$: valid schedule-time horizon; $d_m$: fixed duration of operation type $m$, in seconds. An overbar denotes an upper bound.'),
('Sets',r'$\mathcal E_c$: cleaning segments of chamber $c$, indexed by $e$; $\mathcal V_c$: its production tasks, indexed by $v$, each a $4\times1$ batch or $2\times2$ production cycle.'),
('Sets',r'$\mathcal J_c^D$: auxiliary-loan requests assigned to chamber $c$; $j=(p,r)$ identifies pair $p$ and member position $r$ (D labels auxiliary demand). $\mathcal T_c$: accessible physical auxiliary identities, indexed by $\tau$.'),
('Set',r'$\mathcal R$: shared physical resources, indexed by $r$, including robot actuators, hands, module slots, chambers, and physical auxiliary wafers.'),
('Allowed-unit set',r'$\Gamma_o$: physical units eligible for occupancy task $o$, indexed by $\ell$. VTR units $D_1,D_2$ are dirty hands and $C_1,C_2$ clean hands; digits distinguish hands of one class.'),
('Event maps',r'$\operatorname{in}(w,r),\operatorname{out}(w,r)$: action indices for wafer $w$ entering/leaving constrained region $r$, used to reference event times.'),
('Index sets',r'$\mathcal D_{\rm fix}$: fixed second-stage components, indexed by $d$; $\mathcal Q^w$: waiting items, indexed by $\alpha$ (w labels waiting); $\mathcal I_h$: central indices $(c,q)$ of three consecutive production cycles in one chamber and $2\times2$ chain.'),
('Nonnegative weights',r'$\lambda_1,\lambda_2,\lambda_3,\lambda_4$: weights on total waiting, maximum individual waiting, cadence variation, and soft-limit excess, respectively. Numeric subscripts identify objective terms.'),
('Time inputs',r'$\bar\omega_\alpha$: soft upper limit of waiting item $\alpha$; $\varepsilon_C$: nonnegative second-stage makespan tolerance (C labels completion time), in seconds.'),
]

VARIABLES = [
('Binary/derived',r'$a_{wpr}=1$: product $w$ occupies member position $r\in\{0,1\}$ of pair $p$; $v_p=1$: pair $p$ is active. Derived $d_{pr}=v_p-\sum_w a_{wpr}$ indicates auxiliary filling of that position.'),
('Binary',r'$\mu_{pm}=1$: pair $p$ has operation type $m$; $z_{pc}=1$: it is assigned to chamber $c$, otherwise 0. Product recipe $m_w$ remains an input.'),
('Binary auxiliaries',r'$B_p=1$: pair $p$ contains a product; $B_p^\psi=1$: it contains $2\times2$ products, otherwise 0. Superscript $\psi$ is a recipe label.'),
('Binary/derived',r'$K_{cqm}=1$: cycle $q$ in chamber $c$ has type $m$; $X_{pcq}=1$: pair $p$ participates. Derived $U_{cq}=\sum_mK_{cqm}\in\{0,1\}$ indicates cycle activation.'),
('Binary auxiliaries',r'$X^P_{pcq}=1$: product-containing pair $p$ occupies cycle $(c,q)$ (P labels products). $A^\psi_{pcq},Z^\psi_{pcq}=1$: its first/last exposure as a $2\times2$ product pair, respectively; otherwise 0.'),
('Binary indicator',r'$b_o=1$: candidate action or occupancy task $o$ is active, otherwise 0; activation is linked to layout and optional transfers.'),
('Event times',r'$s_o,e_o$: start/end of action or occupancy task $o$, in seconds. For fixed-duration actions, $e_o=s_o+d_ob_o$; holding endpoints are linked to physical events.'),
('Binary',r'$\gamma_p^{\rm early}=1$: single-source auxiliary wafer in product--auxiliary pair $p$ enters the lock first. $\gamma_p^{\rm late}=1$: it is picked up after product placement on AL. Superscripts label entry options; otherwise 0.'),
('Binary auxiliaries',r'$A_{pcq}=1$: cycle $(c,q)$ is the first occupied by pair $p$ in chamber $c$; $Z_{pcq}=1$: it is the last, otherwise 0.'),
('Aliases/count',r'$S_{cq},E_{cq}$: start/end event times of chamber cycle $(c,q)$, in seconds. $n_{cq}\in\{0,\ldots,H\}$: cumulative production count after that cycle, reset by cleaning.'),
('Binary/derived',r'$f_{pcq}=1$: pair $p$ occupies the accessible front side in cycle $(c,q)$. Derived $\kappa_{cq}=\sum_p(X_{pcq}-A_{pcq})$ marks one retained pair; $\upsilon_{cq}=U_{cq}-\sum_p(X_{pcq}-Z_{pcq})$ marks complete departure after the cycle.'),
('Segment indicators',r'$a_{vce}=1$: production task $v$ belongs to segment $e$ of chamber $c$; $q^{\rm cl}_{ce}=1$: cleaning follows that segment. Both link to the cycle sequence; $q^{\rm cl}$ is an indicator name, not a cycle index.'),
('Binary',r'$g_{j\tau}=1$: loan request $j=(p,r)$ uses physical auxiliary wafer $\tau$, otherwise 0. Request and identity indices distinguish one use from one reusable wafer.'),
('Binary',r'$h_{o\ell}=1$: task $o$ selects physical unit $\ell$; $\gamma_{pa}=1$: pair $p$ is transferred synchronously on eligible atomic leg $a$ at a common location. Special $a=\mathrm{in}$ denotes single-source accompanying entry.'),
('Binary',r'For tasks $o,o^{\prime}$ sharing a unit of resource $r$, $y^r_{oo^{\prime}}=1$ selects $o$ before $o^{\prime}$; 0 selects the reverse. Superscript $r$ identifies the resource; the prime distinguishes tasks.'),
('Nonnegative bound',r'$C_{\max}$: common upper bound on all product-return times $e_{w,\mathrm{return}}$, in seconds, minimized in stage one. The labels return and max are semantic.'),
('Expression/bound',r'$\omega_\alpha$: nonnegative event-time gap minus necessary duration for waiting item $\alpha$; $L_{\max}$: common upper bound on all individual waits, in seconds.'),
('Nonnegative auxiliary',r'$v_{cq}$: upper bound on cadence variation $|S_{c,q+1}-2S_{cq}+S_{c,q-1}|$, in seconds, for three consecutive production cycles centered at $q$ in chamber $c$; defined only for $(c,q)\in\mathcal I_h$.'),
('Nonnegative auxiliary',r'$\eta_\alpha$: upper bound on waiting above soft limit $\bar\omega_\alpha$, in seconds; $\eta_\alpha\ge\max\{0,\omega_\alpha-\bar\omega_\alpha\}$.'),
]
